#!/usr/bin/env python3\nimport sys\nimport random\n\nRECIPES = {\n    "Caprese Salad": {"tomato", "cheese", "basil"},\n    "Peanut Butter Sandwich": {"bread", "peanut butter"},\n    "Veggie Stir Fry": {"carrot", "broccoli", "soy sauce"},\n    "Fruit Salad": {"apple", "banana", "orange"},\n    "Omelette": {"egg", "cheese"}\n}\n\ndef find_possible(recipes, ingredients):\n    possible = []\n    for name, req in recipes.items():\n        if req.issubset(ingredients):\n            possible.append(name)\n    return possible\n\ndef main():\n    if len(sys.argv) < 2:\n        print("Provide at least one ingredient, e.g., 'docker run ... tomato cheese'")\n        sys.exit(1)\n    ingredients = set(arg.lower() for arg in sys.argv[1:])\n    possible = find_possible(RECIPES, ingredients)\n    if not possible:\n        print("No recipes can be made with the given ingredients.")\n        sys.exit(0)\n    dish = random.choice(possible)\n    print(f"Suggested dish: {dish}")\n\nif __name__ == "__main__":\n    main()\n
